#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
    }

    if (k <= 0 || n % k != 0) {
        return 0;
    }

    int changes = 0;

    for (int i = 0; i < k; ++i) {
        int ones = 0;
        int twos = 0;

        for (int j = i; j < n; j += k) {
            if (arr[j] == 1) {
                ++ones;
            } else {
                ++twos;
            }
        }

        changes += min(ones, twos);
    }

    cout << changes << '\n';
    return 0;
}

